import { ParkingLoanRequest, ParkingLoanStatus, Invitation } from '../types.ts';
import { addInvitation } from './invitationService.ts';

const LOANS_STORAGE_KEY = 'condominiumParkingLoans';

export const getParkingLoans = (): ParkingLoanRequest[] => {
  const loansJson = localStorage.getItem(LOANS_STORAGE_KEY);
  return loansJson ? JSON.parse(loansJson) : [];
};

export const saveLoans = (loans: ParkingLoanRequest[]) => {
  localStorage.setItem(LOANS_STORAGE_KEY, JSON.stringify(loans));
};

export const createParkingLoanRequest = (data: Omit<ParkingLoanRequest, 'id' | 'status' | 'createdAt'>): ParkingLoanRequest => {
  const loans = getParkingLoans();
  const newLoan: ParkingLoanRequest = {
    ...data,
    id: `LOAN-${Date.now()}`,
    status: ParkingLoanStatus.PENDING,
    createdAt: new Date().toISOString(),
  };
  saveLoans([newLoan, ...loans]);
  return newLoan;
};

export const completeParkingLoan = (
    loanId: string, 
    visitorData: { name: string; plate: string; rut: string; validUntil: string }
): Invitation | null => {
  const loans = getParkingLoans();
  const loanIndex = loans.findIndex(l => l.id === loanId);

  if (loanIndex === -1) return null;
  const loan = loans[loanIndex];

  // Crear invitación de vehículo
  const newInvitation = addInvitation({
    createdByUserId: loan.borrowerId,
    createdByUserName: loan.borrowerName,
    validFrom: new Date().toISOString(),
    validUntil: visitorData.validUntil,
    type: 'vehicle',
    apartment: loan.borrowerApt,
    licensePlate: visitorData.plate.toUpperCase(),
    guestName: visitorData.name,
    guestIdDocument: visitorData.rut,
    notes: `Uso de Estac. ${loan.spot} prestado por ${loan.lenderName} (${loan.lenderApt})`,
    isParkingLoan: true,
    loanedByUserId: loan.lenderId,
    loanedByUserName: loan.lenderName,
    loanedSpot: loan.spot,
  });

  loans[loanIndex] = {
    ...loan,
    status: ParkingLoanStatus.COMPLETED,
    invitationId: newInvitation.id,
    visitorName: visitorData.name,
    visitorPlate: visitorData.plate,
  };

  saveLoans(loans);
  return newInvitation;
};

export const cancelParkingLoan = (loanId: string) => {
    const loans = getParkingLoans();
    const updated = loans.filter(l => l.id !== loanId);
    saveLoans(updated);
};

import React, { useState, useEffect, useMemo } from 'react';
import { DirectoryUser, ParkingLoanRequest, ParkingLoanStatus, SessionUser } from '../../types.ts';
import { getDirectoryUsers } from '../../services/directoryService.ts';
import { getParkingLoans, createParkingLoanRequest, completeParkingLoan, cancelParkingLoan } from '../../services/parkingLoanService.ts';
import SearchIcon from '../icons/SearchIcon.tsx';
import ParkingIcon from '../icons/ParkingIcon.tsx';
import UserIcon from '../icons/UserIcon.tsx';
import CheckCircleIcon from '../icons/CheckCircleIcon.tsx';

interface ParkingLoanManagerProps {
  currentUser: SessionUser;
  userProfile: DirectoryUser;
}

const ParkingLoanManager: React.FC<ParkingLoanManagerProps> = ({ currentUser, userProfile }) => {
  const [loans, setLoans] = useState<ParkingLoanRequest[]>([]);
  const [neighborSearch, setNeighborSearch] = useState('');
  const [selectedNeighbor, setSelectedNeighbor] = useState<DirectoryUser | null>(null);
  const [selectedSpot, setSelectedSpot] = useState('');
  const [activeTab, setActiveTab] = useState<'send' | 'received'>('send');

  // Form para completar préstamo recibido
  const [completingLoan, setCompletingLoan] = useState<ParkingLoanRequest | null>(null);
  const [visitorName, setVisitorName] = useState('');
  const [visitorPlate, setVisitorPlate] = useState('');
  const [visitorRut, setVisitorRut] = useState('');

  const allDirectoryUsers = useMemo(() => getDirectoryUsers().filter(u => u.id !== userProfile.id), [userProfile.id]);

  const mySpots = useMemo(() => [
    ...(userProfile.unitParkingSpots || []),
    ...(userProfile.vehicles || []).map(v => v.parkingSpot).filter((s): s is string => !!s)
  ], [userProfile]);

  useEffect(() => {
    setLoans(getParkingLoans());
  }, []);

  const neighbors = useMemo(() => {
    if (neighborSearch.length < 2) return [];
    return allDirectoryUsers.filter(u => 
        u.name.toLowerCase().includes(neighborSearch.toLowerCase()) || 
        u.apartment?.toLowerCase().includes(neighborSearch.toLowerCase())
    ).slice(0, 5);
  }, [neighborSearch, allDirectoryUsers]);

  const handleSendLoan = () => {
    if (!selectedNeighbor || !selectedSpot) return;

    createParkingLoanRequest({
        lenderId: currentUser.id,
        lenderName: userProfile.name,
        lenderApt: userProfile.apartment || 'N/A',
        borrowerId: selectedNeighbor.authUserId || selectedNeighbor.id,
        borrowerName: selectedNeighbor.name,
        borrowerApt: selectedNeighbor.apartment || 'N/A',
        spot: selectedSpot,
    });

    setLoans(getParkingLoans());
    setSelectedNeighbor(null);
    setNeighborSearch('');
    setSelectedSpot('');
    alert(`Solicitud enviada a ${selectedNeighbor.name}`);
  };

  const handleCompleteReceived = (e: React.FormEvent) => {
    e.preventDefault();
    if (!completingLoan) return;

    const validUntil = new Date();
    validUntil.setHours(validUntil.getHours() + 12); // Válido por 12 horas

    completeParkingLoan(completingLoan.id, {
        name: visitorName,
        plate: visitorPlate,
        rut: visitorRut,
        validUntil: validUntil.toISOString(),
    });

    alert("Invitación generada exitosamente. El dueño del estacionamiento podrá ver los datos del vehículo.");
    setLoans(getParkingLoans());
    setCompletingLoan(null);
    setVisitorName('');
    setVisitorPlate('');
    setVisitorRut('');
  };

  const mySentLoans = loans.filter(l => l.lenderId === currentUser.id);
  const myReceivedLoans = loans.filter(l => l.borrowerId === currentUser.id);

  return (
    <div className="space-y-6">
      <div className="flex border-b">
        <button onClick={() => setActiveTab('send')} className={`flex-1 py-2 text-sm font-medium ${activeTab === 'send' ? 'border-b-2 border-sky-600 text-sky-600' : 'text-slate-500'}`}>Prestar a un Vecino</button>
        <button onClick={() => setActiveTab('received')} className={`flex-1 py-2 text-sm font-medium ${activeTab === 'received' ? 'border-b-2 border-sky-600 text-sky-600' : 'text-slate-500'}`}>Recibidos ({myReceivedLoans.filter(l => l.status === ParkingLoanStatus.PENDING).length})</button>
      </div>

      {activeTab === 'send' ? (
        <div className="space-y-4 bg-slate-50 p-4 rounded-lg">
          <h4 className="font-semibold text-slate-800 flex items-center gap-2"><ParkingIcon className="w-5 h-5"/> Prestar mi estacionamiento</h4>
          <div>
            <label className="block text-xs font-medium text-slate-600">1. Selecciona tu Estacionamiento</label>
            <select value={selectedSpot} onChange={e => setSelectedSpot(e.target.value)} className="w-full mt-1 p-2 border rounded-md text-sm bg-white">
                <option value="">-- Elige uno --</option>
                {mySpots.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
          <div className="relative">
            <label className="block text-xs font-medium text-slate-600">2. Busca al Vecino Beneficiario</label>
            <div className="relative mt-1">
                <input type="text" value={neighborSearch} onChange={e => {setNeighborSearch(e.target.value); setSelectedNeighbor(null);}} placeholder="Nombre o Apto..." className="w-full pl-8 pr-4 py-2 border rounded-md text-sm"/>
                <SearchIcon className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400"/>
            </div>
            {neighborSearch && !selectedNeighbor && (
                <ul className="absolute z-10 w-full bg-white border rounded-md shadow-lg mt-1 max-h-40 overflow-y-auto">
                    {neighbors.map(n => (
                        <li key={n.id} onClick={() => {setSelectedNeighbor(n); setNeighborSearch(`${n.name} (${n.apartment})`);}} className="p-2 hover:bg-sky-50 cursor-pointer text-sm">
                            {n.name} - {n.apartment}
                        </li>
                    ))}
                </ul>
            )}
          </div>
          <button disabled={!selectedNeighbor || !selectedSpot} onClick={handleSendLoan} className="w-full py-2 bg-sky-600 text-white rounded-md font-semibold disabled:opacity-50">Enviar Autorización</button>

          <div className="mt-6 pt-4 border-t">
              <h5 className="text-xs font-bold text-slate-500 uppercase mb-2">Historial de Préstamos Enviados</h5>
              <div className="space-y-2">
                {mySentLoans.map(l => (
                    <div key={l.id} className="text-xs p-2 bg-white border rounded flex justify-between items-center">
                        <div>
                            <p className="font-medium text-slate-700">Para: {l.borrowerName} ({l.borrowerApt})</p>
                            <p className="text-slate-500">Estac: {l.spot} | {l.status === 'pending' ? '⏳ Esperando visita' : `✅ Visita: ${l.visitorPlate}`}</p>
                        </div>
                        {l.status === 'pending' && <button onClick={() => {cancelParkingLoan(l.id); setLoans(getParkingLoans());}} className="text-red-500">Cancelar</button>}
                    </div>
                ))}
              </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
            {completingLoan ? (
                <form onSubmit={handleCompleteReceived} className="bg-indigo-50 p-4 rounded-lg border border-indigo-200 space-y-4">
                    <h4 className="font-bold text-indigo-800">Completar Datos de Visita</h4>
                    <p className="text-xs text-indigo-600">Usarás el estacionamiento {completingLoan.spot} de {completingLoan.lenderName}.</p>
                    <div>
                        <label className="block text-xs font-medium">Nombre Visitante</label>
                        <input type="text" value={visitorName} onChange={e => setVisitorName(e.target.value)} required className="w-full p-2 border rounded mt-1"/>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                        <div>
                            <label className="block text-xs font-medium">Patente</label>
                            <input type="text" value={visitorPlate} onChange={e => setVisitorPlate(e.target.value.toUpperCase())} required className="w-full p-2 border rounded mt-1"/>
                        </div>
                        <div>
                            <label className="block text-xs font-medium">RUT Visitante</label>
                            <input type="text" value={visitorRut} onChange={e => setVisitorRut(e.target.value)} required className="w-full p-2 border rounded mt-1"/>
                        </div>
                    </div>
                    <div className="flex gap-2">
                        <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded font-bold">Generar Invitación</button>
                        <button type="button" onClick={() => setCompletingLoan(null)} className="px-4 py-2 bg-slate-200 rounded">Volver</button>
                    </div>
                </form>
            ) : (
                <div className="space-y-2">
                    {myReceivedLoans.length === 0 && <p className="text-center text-slate-400 py-10 text-sm">No has recibido préstamos de estacionamiento.</p>}
                    {myReceivedLoans.map(l => (
                        <div key={l.id} className={`p-3 rounded-lg border flex justify-between items-center ${l.status === 'pending' ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-slate-200 opacity-60'}`}>
                            <div>
                                <p className="font-bold text-slate-800">{l.lenderName} te presta su lugar</p>
                                <p className="text-xs text-slate-600">Estacionamiento: <span className="font-bold">{l.spot}</span></p>
                                {l.status === 'completed' && <p className="text-xs text-green-600 font-medium">Invitación: {l.invitationId}</p>}
                            </div>
                            {l.status === 'pending' && (
                                <button onClick={() => setCompletingLoan(l)} className="px-3 py-1.5 bg-indigo-600 text-white text-xs font-bold rounded hover:bg-indigo-700">
                                    Usar Préstamo
                                </button>
                            )}
                        </div>
                    ))}
                </div>
            )}
        </div>
      )}
    </div>
  );
};

export default ParkingLoanManager;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AppSettings, SessionUser, DirectoryUser, DirectoryVehicle, Notification, NotificationStatus, NotificationType } from '../types.ts';
import { getAppSettings, saveAppSettings } from '../services/settingsService.ts';
import { findDirectoryUserByAuthId, updateDirectoryUser, getDirectoryUsers } from '../services/directoryService.ts';
import { updateNotification } from '../services/notificationService.ts';
import { formatPhoneNumber } from '../services/validationService.ts';
import SettingsIcon from './icons/SettingsIcon.tsx'; 
import PasswordConfirmModal from './Auth/PasswordConfirmModal.tsx';
import { verifyPassword, changeSuperuserPassword, validatePassword } from '../services/authService.ts';
import UserIcon from './icons/UserIcon.tsx';
import CarIcon from './icons/CarIcon.tsx';
import TrashIcon from './icons/TrashIcon.tsx';
import EyeIcon from './icons/EyeIcon.tsx';
import EyeSlashIcon from './icons/EyeSlashIcon.tsx';
import BellIcon from './icons/BellIcon.tsx';
import PackageIcon from './icons/PackageIcon.tsx';
import FoodIcon from './icons/FoodIcon.tsx';
import PasswordStrengthIndicator from './PasswordStrengthIndicator.tsx';
import CheckCircleIcon from './icons/CheckCircleIcon.tsx';
import ParkingLoanManager from './Parking/ParkingLoanManager.tsx';
import ParkingIcon from './icons/ParkingIcon.tsx';


interface SettingsScreenProps {
  onSettingsSaved: (settings: AppSettings) => void;
  onSendManualReport: () => { success: boolean; message: string };
  entryCount: number;
  currentGlobalSettings: AppSettings | null;
  isCondominiumNameRequired?: boolean;
  isCurrentUserSuperuser: boolean;
  onClearEntries: () => void;
  currentUser: SessionUser | null;
  notifications: Notification[];
  onNotificationsUpdated: () => void;
}

const initialVehicleFormState: Omit<DirectoryVehicle, 'id'> = {
  licensePlate: '',
  parkingSpot: '',
  notes: '',
};

const UserProfileEditor: React.FC<{
  currentUser: SessionUser;
  notifications: Notification[];
  onProfileUpdated: (msg: string) => void;
  onNotificationsUpdated: () => void;
  showFeedback: (type: 'success' | 'error', text: string) => void;
}> = ({ currentUser, notifications, onProfileUpdated, onNotificationsUpdated, showFeedback }) => {

  const [profileData, setProfileData] = useState<DirectoryUser | null>(null);
  const [vehicleFormData, setVehicleFormData] = useState<Omit<DirectoryVehicle, 'id'>>(initialVehicleFormState);
  const [vehiclePlateError, setVehiclePlateError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'profile' | 'parking'>('profile');

  useEffect(() => {
    const userProfile = findDirectoryUserByAuthId(currentUser.id);
    if (userProfile) {
      setProfileData(JSON.parse(JSON.stringify(userProfile))); 
    }
    setIsLoading(false);
  }, [currentUser.id]);

  const userNotifications = useMemo(() => {
    if (!profileData) return [];
    return notifications
        .filter(n => n.recipientDirUserId === profileData.id && n.status !== NotificationStatus.DELIVERED)
        .sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [notifications, profileData]);

  const handleAcknowledgeNotification = (notificationId: string) => {
    updateNotification(notificationId, { 
      status: NotificationStatus.ACKNOWLEDGED,
      acknowledgedAt: new Date().toISOString(),
    });
    onNotificationsUpdated();
    showFeedback('success', 'Notificación marcada como leída.');
  };


  const handleProfileInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setProfileData(prev => prev ? { ...prev, [name]: value } : null);
  };

  const handlePhoneBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setProfileData(prev => prev ? { ...prev, [name]: formatPhoneNumber(value) } : null);
  };

  const handleVehicleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setVehicleFormData(prev => ({...prev, [name]: value.toUpperCase()}));
    if (name === 'licensePlate' && value) setVehiclePlateError('');
  };

  const handleAddVehicle = () => {
    if (!profileData) return;
    const trimmedPlate = vehicleFormData.licensePlate.trim();
    if (!trimmedPlate) {
        setVehiclePlateError('La placa es obligatoria.');
        return;
    }
    if (profileData.vehicles.some(v => v.licensePlate === trimmedPlate)) {
        setVehiclePlateError('Esta placa ya ha sido agregada.');
        return;
    }
    const allUsers = getDirectoryUsers();
    const isGloballyUnique = !allUsers.some(user => user.id !== profileData.id && user.vehicles.some(v => v.licensePlate === trimmedPlate));
    if (!isGloballyUnique) {
      setVehiclePlateError('Esta placa ya está registrada por otro usuario en el directorio.');
      return;
    }

    setVehiclePlateError('');
    const newVehicle: DirectoryVehicle = {
        id: `temp-${Date.now()}`,
        ...vehicleFormData,
        licensePlate: trimmedPlate,
    };
    setProfileData(prev => prev ? { ...prev, vehicles: [...prev.vehicles, newVehicle] } : null);
    setVehicleFormData(initialVehicleFormState);
  };

  const handleRemoveVehicle = (vehicleId: string) => {
    setProfileData(prev => prev ? { ...prev, vehicles: prev.vehicles.filter(v => v.id !== vehicleId) } : null);
  };

  const handleProfileSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!profileData) {
      showFeedback('error', 'No se pudo guardar, perfil no encontrado.');
      return;
    }
    if (!profileData.name.trim()) {
      showFeedback('error', 'El nombre no puede estar vacío.');
      return;
    }

    const finalVehicles = profileData.vehicles.map(v => ({
      ...v,
      id: v.id.startsWith('temp-') ? Date.now().toString() + Math.random().toString(36).substring(2, 9) : v.id,
    }));

    const updates: Partial<DirectoryUser> = {
      name: profileData.name,
      phone: profileData.phone,
      notes: profileData.notes,
      vehicles: finalVehicles,
    };

    updateDirectoryUser(profileData.id, updates);
    onProfileUpdated('Tu perfil ha sido actualizado exitosamente.');
  };

  if (isLoading) {
    return <p className="text-center text-slate-500">Cargando perfil...</p>;
  }
  if (!profileData) {
    return <p className="text-center text-red-600">No se pudo encontrar tu perfil en el directorio. Por favor, contacta al administrador.</p>;
  }

  return (
    <div className="space-y-6">
      {userNotifications.length > 0 && (
          <fieldset className="border-2 border-indigo-300 bg-indigo-50 p-4 rounded-lg">
            <legend className="text-lg font-semibold text-indigo-700 px-2 flex items-center gap-2">
                <BellIcon className="w-5 h-5"/>Notificaciones Pendientes
            </legend>
            <div className="space-y-3 mt-2 max-h-60 overflow-y-auto pr-2">
                {userNotifications.map(n => (
                    <div key={n.id} className="bg-white p-3 rounded-md shadow-sm border flex justify-between items-start gap-3">
                        <div className="flex items-start gap-3">
                            <div className="flex-shrink-0 pt-0.5">
                                {n.type === NotificationType.PACKAGE ? <PackageIcon className="w-6 h-6 text-sky-600"/> : <FoodIcon className="w-6 h-6 text-orange-500"/>}
                            </div>
                            <div>
                                <p className="font-semibold text-slate-800">
