export enum EntryType {
  PERSON = 'persona',
  VEHICLE = 'vehiculo',
}

export enum View {
  REGISTER_VISIT = 'register_visit',
  QUICK_ACCESS = 'quick_access',
  VIEW_ENTRIES = 'view_entries',
  SETTINGS = 'settings',
  USER_DIRECTORY = 'user_directory',
  INVITATIONS = 'invitations',
  NOTIFICATIONS = 'notifications',
  PROFILES = 'profiles',
  VISITOR_AUTHORIZATION = 'visitor_authorization',
  PARKING = 'parking',
}

export interface BaseEntry {
  id: string;
  timestamp: string;
  type: EntryType;
  status?: 'pending' | 'approved' | 'rejected';
}

export interface PersonEntry extends BaseEntry {
  type: EntryType.PERSON;
  name: string;
  idDocument: string;
  apartment?: string;
  authorizedBy?: string; 
  invitationId?: string;
}

export interface VehicleEntry extends BaseEntry {
  type: EntryType.VEHICLE;
  licensePlate: string;
  driverName?: string;
  parkingSpot?: string;
  authorizedBy?: string;
  invitationId?: string;
}

export type CondominiumEntry = PersonEntry | VehicleEntry;

export interface User { 
  id: string;
  username: string;
  passwordHash: string; 
  email: string;
  isApprovedByAdmin: boolean;
  passwordResetToken?: string; 
  passwordResetTokenExpires?: number;
